17	import { IEditorContribution } from '../../../common/editorCommon.js';
18	import { EditorContextKeys } from '../../../common/editorContextKeys.js';
19	import { IEditorWorkerService } from '../../../common/services/editorWorker.js';
20	import { ILanguageFeaturesService } from '../../../common/services/languageFeatures.js';
21	import { formatDocumentRangesWithSelectedProvider, formatDocumentWithSelectedProvider, FormattingMode, getOnTypeFormattingEdits } from './format.js';
22	import { FormattingEdit } from './formattingEdit.js';
23	import * as nls from '../../../../nls.js';
24	import { AccessibilitySignal, IAccessibilitySignalService } from '../../../../platform/accessibilitySignal/browser/accessibilitySignalService.js';
25	import { CommandsRegistry, ICommandService } from '../../../../platform/commands/common/commands.js';
