212	class FormatDocumentAction extends EditorAction {
213	
214		constructor() {
215			super({
216				id: 'editor.action.formatDocument',
217				label: nls.localize2('formatDocument.label', "Format Document"),
218				precondition: ContextKeyExpr.and(EditorContextKeys.notInCompositeEditor, EditorContextKeys.writable, EditorContextKeys.hasDocumentFormattingProvider),
219				kbOpts: {
220					kbExpr: EditorContextKeys.editorTextFocus,
221					primary: KeyMod.Shift | KeyMod.Alt | KeyCode.KeyF,
222					linux: { primary: KeyMod.CtrlCmd | KeyMod.Shift | KeyCode.KeyI },
223					weight: KeybindingWeight.EditorContrib
224				},
225				contextMenuOpts: {
226					group: '1_modification',
