228				}
229			});
230		}
231	
232		async run(accessor: ServicesAccessor, editor: ICodeEditor): Promise<void> {
233			if (editor.hasModel()) {
234				const instaService = accessor.get(IInstantiationService);
235				const progressService = accessor.get(IEditorProgressService);
236				await progressService.showWhile(
237					instaService.invokeFunction(formatDocumentWithSelectedProvider, editor, FormattingMode.Explicit, Progress.None, CancellationToken.None, true),
238					250
239				);
240			}
241		}
242	}
243	
244	class FormatSelectionAction extends EditorAction {
245	
246		constructor() {
247			super({
248				id: 'editor.action.formatSelection',
249				label: nls.localize2('formatSelection.label', "Format Selection"),
250				precondition: ContextKeyExpr.and(EditorContextKeys.writable, EditorContextKeys.hasDocumentSelectionFormattingProvider),
251				kbOpts: {
252					kbExpr: EditorContextKeys.editorTextFocus,
253					primary: KeyChord(KeyMod.CtrlCmd | KeyCode.KeyK, KeyMod.CtrlCmd | KeyCode.KeyF),
254					weight: KeybindingWeight.EditorContrib
255				},
256				contextMenuOpts: {
257					when: EditorContextKeys.hasNonEmptySelection,
258					group: '1_modification',
259					order: 1.31
260				}
261			});
262		}
263	
264		async run(accessor: ServicesAccessor, editor: ICodeEditor): Promise<void> {
265			if (!editor.hasModel()) {
266				return;
267			}
268			const instaService = accessor.get(IInstantiationService);
269			const model = editor.getModel();
270	
271			const ranges = editor.getSelections().map(range => {
272				return range.isEmpty()
273					? new Range(range.startLineNumber, 1, range.startLineNumber, model.getLineMaxColumn(range.startLineNumber))
274					: range;
275			});
276	
277			const progressService = accessor.get(IEditorProgressService);
278			await progressService.showWhile(
279				instaService.invokeFunction(formatDocumentRangesWithSelectedProvider, editor, ranges, FormattingMode.Explicit, Progress.None, CancellationToken.None, true),
280				250
281			);
282		}
283	}
284	
285	registerEditorContribution(FormatOnType.ID, FormatOnType, EditorContributionInstantiation.BeforeFirstInteraction);
286	registerEditorContribution(FormatOnPaste.ID, FormatOnPaste, EditorContributionInstantiation.BeforeFirstInteraction);
287	registerEditorAction(FormatDocumentAction);
288	registerEditorAction(FormatSelectionAction);
289	
290	// this is the old format action that does both (format document OR format selection)
291	// and we keep it here such that existing keybinding configurations etc will still work
292	CommandsRegistry.registerCommand('editor.action.format', async accessor => {
293		const editor = accessor.get(ICodeEditorService).getFocusedCodeEditor();
294		if (!editor || !editor.hasModel()) {
295			return;
296		}
297		const commandService = accessor.get(ICommandService);
298		if (editor.getSelection().isEmpty()) {
299			await commandService.executeCommand('editor.action.formatDocument');
300		} else {
301			await commandService.executeCommand('editor.action.formatSelection');
302		}
303	});
