82	export interface IFormattingEditProviderSelector {
83		<T extends (DocumentFormattingEditProvider | DocumentRangeFormattingEditProvider)>(formatter: T[], document: ITextModel, mode: FormattingMode, kind: FormattingKind): Promise<T | undefined>;
84	}
85	
86	export abstract class FormattingConflicts {
87	
88		private static readonly _selectors = new LinkedList<IFormattingEditProviderSelector>();
89	
90		static setFormatterSelector(selector: IFormattingEditProviderSelector): IDisposable {
91			const remove = FormattingConflicts._selectors.unshift(selector);
92			return { dispose: remove };
93		}
94	
95		static async select<T extends (DocumentFormattingEditProvider | DocumentRangeFormattingEditProvider)>(formatter: T[], document: ITextModel, mode: FormattingMode, kind: FormattingKind): Promise<T | undefined> {
96			if (formatter.length === 0) {
97				return undefined;
98			}
99			const selector = Iterable.first(FormattingConflicts._selectors);
100			if (selector) {
101				return await selector(formatter, document, mode, kind);
102			}
103			return undefined;
104		}
105	}
