438	export function getOnTypeFormattingEdits(
439		workerService: IEditorWorkerService,
440		languageFeaturesService: ILanguageFeaturesService,
441		model: ITextModel,
442		position: Position,
443		ch: string,
444		options: FormattingOptions,
445		token: CancellationToken
446	): Promise<TextEdit[] | null | undefined> {
447	
448		const providers = languageFeaturesService.onTypeFormattingEditProvider.ordered(model);
449	
450		if (providers.length === 0) {
451			return Promise.resolve(undefined);
452		}
453	
454		if (providers[0].autoFormatTriggerCharacters.indexOf(ch) < 0) {
455			return Promise.resolve(undefined);
456		}
457	
458		return Promise.resolve(providers[0].provideOnTypeFormattingEdits(model, position, ch, options, token)).catch(onUnexpectedExternalError).then(edits => {
459			return workerService.computeMoreMinimalEdits(model.uri, edits);
460		});
461	}
