463	function isFormattingOptions(obj: unknown): obj is FormattingOptions {
464		const candidate = obj as FormattingOptions | undefined;
465	
466		return !!candidate && typeof candidate === 'object' && typeof candidate.tabSize === 'number' && typeof candidate.insertSpaces === 'boolean';
467	}
